        "content": "The complete solver script (`solve.py`) is included below.",
        "code": "#!/usr/bin/env python3\nimport hashlib\nimport json\nimport urllib.request\nimport urllib.parse\n\nBASE = \"https://bounty-hunter-87fc558fd3cf.inst3.ctf.fortid.com\"\nP = 35182531786822156541290684230036086178800502148536840364113258180206318266211\n\ndef get(path):\n    with urllib.request.urlopen(BASE + path) as r:\n        return json.loads(r.read().decode())\n\ndef F(x):\n    return int(x) % P\n\ndef h_int(*parts):\n    h = hashlib.sha256()\n    for part in parts:\n        b = part if isinstance(part, bytes) else str(part).encode()\n        h.update(len(b).to_bytes(4, \"big\"))\n        h.update(b)\n    return int.from_bytes(h.digest(), \"big\") % P\n\ndef commit(coeffs):\n    h = hashlib.sha256(b\"TwinFold coefficient commitment\")\n    h.update(len(coeffs).to_bytes(4, \"big\"))\n    for c in coeffs:\n        h.update(F(c).to_bytes(32, \"big\"))\n    return h.hexdigest()\n\ndef eval_poly(coeffs, x):\n    y = 0\n    for c in reversed(coeffs):\n        y = (y * F(x) + F(c)) % P\n    return y\n\ndef point_bits(report_id, field, manifest):\n    enc = manifest[\"encoding\"]\n    def bits(x, n):\n        return [(x >> i) & 1 for i in range(n)]\n    return bits(report_id, enc[\"report_id_bits\"]) + bits(enc[\"columns\"][field], enc[\"column_bits\"])\n\ndef make_linear_at(x, a, b):\n    # Return c0,c1 such that c0+c1*x=a and c0-c1*x=b.\n    inv2 = pow(2, P - 2, P)\n    return [F((a + b) * inv2), F((a - b) * pow(2 * F(x), P - 2, P))]\n\ndef main():\n    manifest = get(\"/api/transparency/snapshots/latest/manifest.json\")\n    vector = []\n    for shard in manifest[\"shards\"]:\n        vector += [F(x) for x in get(shard[\"path\"])[\"values\"]]\n\n    report_id = 271\n    field = \"payout_authorized\"\n    claimed = 1\n    bits = point_bits(report_id, field, manifest)\n    n = len(bits)\n    rho = h_int(\"TwinFold-v2\", manifest[\"snapshot_id\"], manifest[\"commitment\"], report_id, field, claimed)\n    if rho in (0, 1, P - 1):\n        rho = 7\n    xs = [rho]\n    for _ in range(n):\n        xs.append(xs[-1] * xs[-1] % P)\n\n    rounds = []\n    fold_commitments = []\n    coeffs = vector\n\n    # Round zero is forced by the published vector.  Every later polynomial\n    # is only checked at +/- one point, so a degree-one polynomial suffices.\n    for i in range(n):\n        a = eval_poly(coeffs, xs[i])\n        b = eval_poly(coeffs, -xs[i])\n        if i == n - 1:\n            next_coeffs = [claimed]\n            target = claimed\n        else:\n            target = 0\n            if i == 0:\n                # This is the value that the honest first fold must produce.\n                target = ((a + b) * pow(2, P - 2, P)) % P if bits[i] == 0 else ((a - b) * pow(2 * xs[i], P - 2, P)) % P\n            # The next polynomial evaluates to the previous fold at xs[i+1].\n            # Its other evaluation is selected to force the next fold to target.\n            if i < n - 1:\n                next_a = target\n                next_target = claimed if i + 1 == n - 1 else 0\n                next_b = (2 * next_target - next_a) % P if bits[i + 1] == 0 else (next_a - 2 * xs[i + 1] * next_target) % P\n                next_coeffs = make_linear_at(xs[i + 1], next_a, next_b)\n\n        rounds.append({\"a\": str(a), \"b\": str(b), \"next_coeffs\": [str(x) for x in next_coeffs]})\n        fold_commitments.append(commit(next_coeffs))\n        coeffs = next_coeffs\n\n    proof = {\n        \"claimed_value\": str(claimed),\n        \"field\": field,\n        \"fold_commitments\": fold_commitments,\n        \"report_id\": report_id,\n        \"rounds\": rounds,\n        \"scheme\": manifest[\"scheme\"],\n        \"snapshot_id\": manifest[\"snapshot_id\"],\n    }\n    data = json.dumps(proof).encode()\n    req = urllib.request.Request(BASE + \"/api/proof/verify\", data=data, headers={\"content-type\": \"application/json\"})\n    with urllib.request.urlopen(req) as r:\n        verify = r.read().decode()\n    print(\"verify:\", verify)\n\n    form = urllib.parse.urlencode({\"proof\": json.dumps(proof)}).encode()\n    req = urllib.request.Request(BASE + \"/vault\", data=form, headers={\"content-type\": \"application/x-www-form-urlencoded\"})\n    with urllib.request.urlopen(req) as r:\n        vault = r.read().decode()\n    print(vault)\n\nif __name__ == \"__main__\":\n    main()"
