        "code": "#!/usr/bin/env python3\n\"\"\"Recover and verify the intended Baby Rev flag.\"\"\"\n\nimport hashlib\n\nKEYPAD = {\n    **dict.fromkeys(\"abc\", \"2\"),\n    **dict.fromkeys(\"def\", \"3\"),\n    **dict.fromkeys(\"ghi\", \"4\"),\n    **dict.fromkeys(\"jkl\", \"5\"),\n    **dict.fromkeys(\"mno\", \"6\"),\n    **dict.fromkeys(\"pqrs\", \"7\"),\n    **dict.fromkeys(\"tuv\", \"8\"),\n    **dict.fromkeys(\"wxyz\", \"9\"),\n}\n\n\ndef touchtone(words: str) -> str:\n    return \"-\".join(\n        \"\".join(KEYPAD.get(char, char) for char in word)\n        for word in words.split(\"_\")\n    )\n\n\ndef main() -> None:\n    words = \"nokia_3310_is_still_the_most_robust_piece_of_technology_i_have_ever_owned\"\n    flag = \"FortID{\" + words + \"}\"\n    encoded_reversed = (\n        \"33696-7383-3824-4-9465664238-36-32347-878267-8766-348-55487-74-0133-24566\"\n    )\n    expected_hash = (\n        \"3576c495f89236515fbbfbfb519dceb9899122e92460d418d2ce37a1ff357e0c\"\n    )\n    assert touchtone(words)[::-1] == encoded_reversed\n    assert len(flag) == 81\n    assert hashlib.sha256(flag.encode()).hexdigest() == expected_hash\n    print(flag)\n\n\nif __name__ == \"__main__\":\n    main()"
