        "title": "Solver Script",
        "content": "The complete solver script (`solve.py`) is included below.",
        "code": "#!/usr/bin/env python3\n\"\"\"Recover the FLAG from the local Checksum (SFSN161) ELF.\n\nThe check is only one byte, but its statically-generated call graph retains an\nordered stream of XOR operations. Each original byte occupies 162 operation\nslots. Zero-XOR operations can be optimized out; allow 0..2 omitted slots per\ncharacter. Reconstruct printable candidate strings with dynamic programming,\nthen resolve the remaining ambiguity using the challenge's semantic hint.\n\nNo network, no external files or writeup required.\n\"\"\"\nfrom __future__ import annotations\n\nfrom functools import lru_cache\nfrom operator import xor\nfrom functools import reduce\nfrom pathlib import Path\nimport re\nimport subprocess\n\nBIN = Path(__file__).with_name('checksum')\nROOTS = {\n    'AZURE_API_KEY': '4f4800fbd67030125774d819d981e9a73dec6b37',\n    'DB_PASSWORD': 'd596da6220389f86c1d95ee0f64e443297c1159a',\n    'MANS_BEST_FRIEND': '9b9436e07bfc893af9111c09d308c4feb1684610',\n    'FLAG': 'defa60ccef758e50fb2f70e838b3d36e5d1aeb71',\n}\n\n\ndef disassemble():\n    return subprocess.check_output(\n        ['objdump', '-d', '-M', 'intel', '--no-show-raw-insn',\n         '--demangle', str(BIN)],\n        text=True, errors='replace')\n\n\ndef parse_graph(asm):\n    graph = {}\n    current = None\n    for line in asm.splitlines():\n        m = re.match(r'([0-9a-f]+) <checksum::checksum_([0-9a-f]{40})_>:',\n                     line.strip())\n        if m:\n            current = int(m.group(1), 16)\n            graph[current] = {'hash':m.group(2), 'ops':[], 'calls':[]}\n            continue\n        if current is None:\n            continue\n        if re.match(r'[0-9a-f]+ <', line.strip()):\n            current = None\n            continue\n        x = re.search(r'xor\\s+BYTE PTR \\[rdi\\],0x([0-9a-f]+)', line)\n        if x:\n            graph[current]['ops'].append(int(x.group(1),16))\n        if re.search(r'not\\s+BYTE PTR \\[rdi\\]', line):\n            graph[current]['ops'].append(0xff)\n        c = re.search(r'call\\s+([0-9a-f]+)\\s+<checksum::checksum_',line)\n        if c:\n            graph[current]['calls'].append(int(c.group(1),16))\n    return graph\n\n\ndef operation_stream(graph, root):\n    \"\"\"Follow call order, including EVERY execution of a shared leaf.\"\"\"\n    def walk(addr):\n        node = graph[addr]\n        # Each function has one byte operation in the generated source.\n        # Optimized-out XOR 0 is retained here as a harmless zero.\n        yield reduce(xor, node['ops'], 0)\n        for child in node['calls']:\n            yield from walk(child)\n    return list(walk(root))\n\n\ndef recover(graph, root, valid):\n    stream = operation_stream(graph, root)\n    n = round(len(stream)/162)\n    pref = [0]\n    for b in stream:\n        pref.append(pref[-1] ^ b)\n\n    @lru_cache(None)\n    def dp(i, offset):\n        if i == n:\n            return [('', ())] if offset == len(stream) else []\n        out = []\n        for width in (162, 161, 160):\n            end = offset+width\n            if end > len(stream):\n                continue\n            ch = chr(pref[end] ^ pref[offset])\n            if not valid(i, n, ch):\n                continue\n            for suffix, widths in dp(i+1, end):\n                out.append((ch + suffix, (width,) + widths))\n        return out\n\n    return stream, dp(0, 0)\n\n\ndef valid_flag(i, n, ch):\n    if i < 6:\n        return ch.isascii() and ch.isalpha()\n    if i == 6:\n        return ch == '{'\n    if i == n-1:\n        return ch == '}'\n    return ch.isascii() and (ch.isalnum() or ch=='_')\n\n\ndef semantic_score(s):\n    \"\"\"Context from challenge description: a CHECKSUM is NOT SECURE.\"\"\"\n    body = s.split('{',1)[1].removesuffix('}')\n    replacements = str.maketrans({'3':'e','5':'s','1':'i','0':'o'})\n    words = [x.lower().translate(replacements) for x in body.split('_')]\n    expected = ['checksum', 'is', 'not', 'secure']\n    return sum(a == b for a,b in zip(words, expected))\n\n\ndef main():\n    graph = parse_graph(disassemble())\n    lookup = {info['hash']:address for address,info in graph.items()}\n    roots = {name:lookup[sha] for name,sha in ROOTS.items()}\n\n    # Independent calibration. The public 3-character secret is \"dog\".\n    dog_stream, dog_candidates = recover(graph, roots['MANS_BEST_FRIEND'],\n        lambda _i,_n,ch:ch.isascii() and ch.isalpha())\n    assert len(dog_stream) == 484\n    assert 'dog' in {s for s,_ in dog_candidates}, 'calibration did not recover dog'\n\n    stream, matches = recover(graph, roots['FLAG'], valid_flag)\n    assert len(stream) == 4850\n    print(f'[*] Functions: {len(graph)}; FLAG XOR operations: {len(stream)}')\n    print(f'[*] Estimated original length: {round(len(stream)/162)}')\n    print('[*] Format-constrained reconstructions:')\n    for s,widths in matches:\n        print(f'    {s}  (score={semantic_score(s)}, missing={162*len(widths)-sum(widths)})')\n\n    if not matches:\n        raise RuntimeError('No solutions. Reassess original per-byte slot count.')\n    ranked = sorted(matches, key=lambda v:semantic_score(v[0]), reverse=True)\n    best, widths = ranked[0]\n    if len(ranked) > 1 and semantic_score(best) == semantic_score(ranked[1][0]):\n        raise RuntimeError('Ambiguous best semantic candidate; no unique result')\n    assert re.fullmatch(r'[A-Za-z]{6}\\{[A-Za-z0-9_]+\\}', best)\n\n    root_checksum = reduce(xor, stream, 0)\n    recovered_checksum = reduce(xor, best.encode('ascii'), 0)\n    assert root_checksum == recovered_checksum == 0x39\n    output = subprocess.check_output([str(BIN)], input=b'FLAG\\n')\n    assert b'Checksum: 39' in output, output\n\n    print(f'[*] Per-byte operation widths: {list(widths)}')\n    print(f'[*] Verified: XOR(flag bytes) = {recovered_checksum:02x}; ELF FLAG = {root_checksum:02x}')\n    print(f'<FLAG>{best}</FLAG>')\n\n\nif __name__ == '__main__':\n    main()"
