        "code": "response = context.request.post(\n    issuer + \"/internal/bot/login\",\n    headers=auth,\n    max_redirects=0\n)\n\npage = context.new_page()\n\npage.goto(\n    issuer + \"/admin\",\n    wait_until=\"domcontentloaded\"\n)\n\npage.locator(\"#issue\").click()\n\npage.wait_for_selector(\n    \"#offer[data-ready='true']\",\n    timeout=45000\n)"
